function [dc, ds] = from_model(jd_tt)
%FROM_MODEL  oceantides.fromModel(jd_tt, tbl) over FES2004: every line's th = doodson . beta, dC += (Cp + Cm) cos th + (Sp + Sm)
%   sin th, dS += (Sp - Sm) cos th - (Cp - Cm) sin th (row-major, stride fes_nmax() + 1).
%   jd_tt: real[1] (passed a plain number)
%   returns dc: real[1][FES_N] (passed a plain number)
%   returns ds: real[1][FES_N] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    dc = zeros(121, 1);
    ds = zeros(121, 1);
    D__FES2004 = asils.models.tidelines.FES2004();
    beta = asils.models.oceantides.doodson(jd_tt);
    st = (asils.models.oceantides.fes_nmax() + 1);
    dc = zeros(121, 1);
    ds = zeros(121, 1);
    for i = (0):((1052) - 1)
        th = 0;
        for j = (0):((6) - 1)
            th = (th + (D__FES2004((i) + 1, (j) + 1) * beta((j) + 1)));
        end
        stn = sin(th);
        ctn = cos(th);
        k = ((fix(D__FES2004((i) + 1, 7)) * st) + fix(D__FES2004((i) + 1, 8)));
        dc((k) + 1) = ((dc((k) + 1) + ((D__FES2004((i) + 1, 9) + D__FES2004((i) + 1, 11)) * ctn)) + ((D__FES2004((i) + 1, 10) + D__FES2004((i) + 1, 12)) * stn));
        ds((k) + 1) = ((ds((k) + 1) + ((D__FES2004((i) + 1, 10) - D__FES2004((i) + 1, 12)) * ctn)) - ((D__FES2004((i) + 1, 9) - D__FES2004((i) + 1, 11)) * stn));
    end
end
